{
  "chapter_index": 2,
  "name": "Intrigues of the Court / রাজসভার ষড়যন্ত্র",
  "chapter_title": "মণিমুক্তো ও ষড়যন্ত্রের জাল",
  "book_name": "LAXMANSEN",
  "book_long_title": "কনৌজ বিজয়: বাংলার গৌরবময় অধ্যায় – বল্লাল সেন ও লক্ষ্মণ সেনের অমর কাহিনি",
  "chapter_summary": "নবদ্বীপের জাঁকজমকপূর্ণ রাজসভায় বল্লাল সেন যখন সমাজ সংস্কার ও শাস্ত্রে নিমগ্ন, তখন পর্দার আড়ালে ঘনিয়ে আসছে সামন্তদের বিদ্রোহ। কলিঙ্গ ও কামরূপের অশুভ ছায়া এবং রাজসভার ভেতরকার বিশ্বাসঘাতকতা যুবরাজ লক্ষ্মণ সেনকে বিচলিত করে তোলে। এরই মাঝে নর্তকী মৃন্ময়ীর আগমনে রহস্যের এক নতুন মাত্রা যোগ হয়।",
  "chapter_segments": [
    {
      "segment_index": 1,
      "name": "setting_the_scene",
      "segment_title": "নবদ্বীপের ঐশ্বর্য ও রাজকীয় সমারোহ",
      "segment_seed": "গৌড়ের রাজধানী নবদ্বীপ তখন আভিজাত্যের শিখরে। রাজসভার স্বর্ণমণ্ডিত স্তম্ভ আর ধূপের সুগন্ধিতে এক মায়াবী পরিবেশ। বল্লাল সেনের সামনে রাখা মুক্তোর মালাগুলো ঝিলিক দিচ্ছে, কিন্তু সেই আলো কি ভবিষ্যতের অন্ধকার ঢাকতে পারবে?"
    },
    {
      "segment_index": 2,
      "name": "status_quo_description",
      "segment_title": "শাস্ত্রচর্চা ও কৌলিন্যের বিতর্ক",
      "segment_seed": "রাজা বল্লাল সেন ব্রাহ্মণ ও পণ্ডিতদের সাথে গভীর তর্কে মগ্ন। মন্ত্রী হালায়ুধ মিশ্র রাজার পাশে বসে নিবিষ্ট মনে শুনছেন কৌলিন্য প্রথার খসড়া। সমাজকে শৃঙ্খলিত করার এই মহৎ উদ্দেশ্য কি সাধারণ মানুষের মনে ক্ষোভের আগুন জ্বালাবে?"
    },
    {
      "segment_index": 3,
      "name": "initial_spark",
      "segment_title": "মৃন্ময়ীর প্রবেশ ও প্রথম দৃষ্টিপাত",
      "segment_seed": "রাজসভার নূপুরের ধ্বনিতে সবার আলাপ থমকে গেল। নর্তকী মৃন্ময়ীর প্রথম প্রবেশ। তার পৈঁচি আর কঙ্কণের শব্দের চেয়েও বেশি ধারালো তার চোখের চাহনি। যুবরাজ লক্ষ্মণ সেনের চোখে চোখ পড়তেই এক মুহূর্তের জন্য সময় থমকে গেল।"
    },
    {
      "segment_index": 4,
      "name": "initial_mystery",
      "segment_title": "নর্তকীর চোখের রহস্য",
      "segment_seed": "মৃন্ময়ীর মুদ্রায় যতটা শিল্প আছে, তার চেয়েও বেশি আছে এক গোপন বার্তা। লক্ষ্মণ সেন অনুভব করেন, এই নর্তকী কেবল বিনোদনের জন্য আসেনি। তার চোখের কোণে কি কোনো গুপ্তচরবৃত্তির সংকেত লুকিয়ে আছে?"
    },
    {
      "segment_index": 5,
      "name": "external_obstacle",
      "segment_title": "কলিঙ্গের ছায়া ও অমাত্যদের বিশ্বাসঘাতকতা",
      "segment_seed": "লক্ষ্মণ সেন লক্ষ্য করেন কিছু সামন্ত রাজা রাজসভায় উপস্থিত থাকলেও তাদের দেহভঙ্গি সন্দেহজনক। কামরূপ ও কলিঙ্গের সাথে গোপনে পত্র বিনিময় হচ্ছে। রাজসভার ঐশ্বর্য এখন এক বারুদের স্তূপের ওপর দাঁড়িয়ে আছে।"
    },
    {
      "segment_index": 6,
